/*
 * A165243  Primes obtained from other primes by pre-concatenating with 2.
 * https://oeis.org/A165243
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn
 * Formula:   a(n) = the nth prime obtained by pre‑concatenating a prime p
 *            with the digit 2 (i.e. a(n) = concat(2, p) where p is prime).
 *            The sequence is generated by iterating over primes p, forming q
 *            = concat_parts(2, p) and keeping those q that are prime. The
 *            results are cached so that calls with arbitrary i...
 * Range:     u8 n <= 5, u16 n <= 42, u32 n <= 42, u64 n <= 42, u128 n <= 42,
 *            big any n
 * Helpers:   concat_parts, is_prime_big, next_prime, seq_alloc_array,
 *            seq_free_array
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>             /* size_t */
#include "../utils/concat_parts.h"
#include "../utils/is_prime_big.h"
#include "../utils/next_prime.h"
#include "../utils/seq_alloc_array.h"
#include "../utils/seq_free_array.h"

static seq_t *cache = NULL;          /* cached sequence values */
static size_t cache_len = 0;         /* number of cached terms */
static size_t cache_cap = 0;         /* current capacity of cache */
static uint64_t last_p = 1;          /* last prime p that was processed */

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;    /* undefined for n == 0, return 0 */

    while (cache_len < n) {
        /* Get the next prime p after the last one processed. */
        uint64_t p = next_prime(last_p);
        last_p = p;

        /* Form q = concat(2, p). */
        seq_t q = concat_parts((idx_t)2, (idx_t)p);

        /* Keep q if it is prime. */
        if (is_prime_big(q)) {
            /* Grow the cache if it is full. */
            if (cache_len + 1 > cache_cap) {
                size_t new_cap = (cache_cap == 0) ? 4 : cache_cap * 2;
                seq_t *tmp = seq_alloc_array(new_cap);
                if (!tmp) return (seq_t)0;   /* allocation failed */

                /* Copy existing terms into the new array. */
                for (size_t i = 0; i < cache_len; ++i) {
                    tmp[i] = cache[i];
                }

                /* Free the old array if it existed. */
                if (cache) seq_free_array(cache);

                cache = tmp;
                cache_cap = new_cap;
            }
            cache[cache_len++] = q;
        }
    }
    return cache[n - 1];
}
